import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = (1 << 20) + 7;
    static final int MAXK = 20;
    static final int INF = (int)1e9 + 7;
    static final long LLINF = (long)1e18 + 7L;
    static final double EPS = 1e-9;
    static final long MOD = 1000000007L;

    static int[][] grid_vals = new int[MAXK][MAXK];
    static int[][] elo_map_vals = new int[MAXK][MAXK];
    static int[] mask_map_vals = new int[MAXN];

    static long[][] dp_vals = new long[MAXN][2];

    static class Pair {
        int first, second;
        Pair(int f, int s) {
            this.first = f;
            this.second = s;
        }
    }

    static int compute_mask_value(List<Pair> edges, boolean flag) {
        int mask_value = 0;
        int size = edges.size();
        for (int i = 0; i < size; i++) {
            for (int j = i + 1; j < size; j++) {
                if (edges.get(i).first != edges.get(j).first && edges.get(i).second != edges.get(j).second) {
                    for (int k = j + 1; k < size; k++) {
                        if (edges.get(i).first != edges.get(k).first && edges.get(j).first != edges.get(k).first
                                && edges.get(i).second != edges.get(k).second && edges.get(j).second != edges.get(k).second) {
                            int index = (flag ? 126 : 0) ^ ((1 << edges.get(i).second) + (1 << edges.get(j).second) + (1 << edges.get(k).second));
                            mask_value |= mask_map_vals[index];
                        }
                    }
                }
            }
        }
        return mask_value;
    }

    static long compute_power(long base, long exponent) {
        if (exponent == 0) return 1;
        long half_pow = compute_power(base, exponent / 2);
        long result = (half_pow * half_pow) % MOD;
        if ((exponent & 1) == 1) result = (result * base) % MOD;
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n = Integer.parseInt(br.readLine());
        for (int i = 1; i <= n; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 1; j <= n; j++) {
                grid_vals[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        int counter = 0;
        for (int i = 1; i <= 6; i++) {
            for (int j = i + 1; j <= 6; j++) {
                for (int k = j + 1; k <= 6; k++) {
                    int index = (1 << i) ^ (1 << j) ^ (1 << k);
                    mask_map_vals[index] = 1 << counter++;
                }
            }
        }

        for (int i = n + 1; i <= 6; i++) {
            grid_vals[i][i] = 100;
        }

        List<Pair> edges = new ArrayList<>();
        n = 6;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                edges.add(new Pair(i, j));
            }
        }

        long inv_100 = compute_power(100, MOD - 2);

        for (int k = 0; k < 2; k++) {
            for (int mask_idx = 0; mask_idx < (1 << 18); mask_idx++) {
                long prob = 1;
                List<Pair> selected_edges = new ArrayList<>();
                for (int j = 0; j < 18; j++) {
                    if (((1 << j) & mask_idx) != 0) {
                        int row = edges.get(j + k * 18).first;
                        int col = edges.get(j + k * 18).second;
                        prob = (prob * grid_vals[row][col]) % MOD;
                        prob = (prob * inv_100) % MOD;
                        selected_edges.add(new Pair(row, col));
                    } else {
                        int row = edges.get(j + k * 18).first;
                        int col = edges.get(j + k * 18).second;
                        int val = grid_vals[row][col];
                        long temp = (100 - val);
                        prob = (prob * temp) % MOD;
                        prob = (prob * inv_100) % MOD;
                    }
                }
                int current_mask = compute_mask_value(selected_edges, k == 1);
                dp_vals[current_mask][k] = (dp_vals[current_mask][k] + prob) % MOD;
            }
        }

        long final_result = 1;
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < (1 << 20); j++) {
                if (((1 << i) & j) != 0) {
                    dp_vals[j][0] = (dp_vals[j][0] + dp_vals[j ^ (1 << i)][0]) % MOD;
                }
            }
        }

        for (int i = 0; i < (1 << 20); i++) {
            long val1 = dp_vals[i][0];
            long val2 = dp_vals[((1 << 20) - 1) ^ i][1];
            long temp = (val1 * val2) % MOD;
            final_result = (final_result - temp + MOD) % MOD;
        }

        System.out.println(final_result);
    }
}
